fn step_bytes(steps: &[Step]) -> usize {
    let mut total = 0_usize;
    for step in steps {
        total = total.saturating_add(match step {
            Step::ReplaceDoc { doc, .. } => usize::try_from(doc.size().0).unwrap_or(usize::MAX),
            Step::Replace { slice, .. } | Step::ReplaceAround { slice, .. } => slice
                .text
                .len()
                .saturating_add(usize::try_from(slice.content.size().0).unwrap_or(usize::MAX)),
            Step::AddMark { .. }
            | Step::RemoveMark { .. }
            | Step::SetNodeAttr { .. }
            | Step::SetDocAttr { .. }
            | Step::SetInlineAttr { .. }
            | Step::SetMarkAttr { .. } => 0,
        });
    }
    total
}
