    /// Maximum attributes per mark.
    pub max_mark_attrs: u8,
    /// Maximum bytes in one attribute string.
    pub max_attr_string_bytes: u32,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            max_doc_bytes: 64 * 1024 * 1024,
            max_block_text_bytes: 1024 * 1024,
            max_depth: 64,
